import fs from 'node:fs';
const envelope = JSON.parse(fs.readFileSync(0, 'utf8'));
const sequence = envelope.input.sequence.trim().toUpperCase();
if (!/^[ACGT]+$/.test(sequence)) throw new Error('baseline accepts plain DNA only');
const gcCount = [...sequence].filter(base => base === 'G' || base === 'C').length;
process.stdout.write(JSON.stringify({ length: sequence.length, gcFraction: gcCount / sequence.length }));
